1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"os"
7		"strings"
8		"testing"
9	)
10	
11	type cliResult struct {
12		code int
13		out  string
14		err  string
15	}
16	
17	func runCLIWith(t *testing.T, args []string, stdin string) cliResult {
18		t.Helper()
19		var out, errBuf bytes.Buffer
20		code := runCLI(args, strings.NewReader(stdin), &out, &errBuf)
21		return cliResult{code: code, out: out.String(), err: errBuf.String()}
22	}
23	
24	func decodeOut(t *testing.T, s string) map[string]any {
25		t.Helper()
26		var v map[string]any
27		if err := json.Unmarshal([]byte(s), &v); err != nil {
28			t.Fatalf("output is not JSON: %v\n%s", err, s)
29		}
30		return v
31	}
32	
33	func TestCLIVersionAndDemo(t *testing.T) {
34		if r := runCLIWith(t, []string{"version"}, ""); r.code != 0 || !strings.Contains(r.out, "payflow 0.2.0") {
35			t.Fatalf("version: %+v", r)
36		}
37		// 无参数保持历史默认行为：运行 demo。
38		if r := runCLIWith(t, nil, ""); r.code != 0 || !strings.Contains(r.out, "reconciliation gaps") {
39			t.Fatalf("default demo: code=%d out=%q", r.code, r.out)
40		}
41		if r := runCLIWith(t, []string{"demo"}, ""); r.code != 0 || !strings.Contains(r.out, "intent=pay-1") {
42			t.Fatalf("demo: %+v", r)
43		}
44		if r := runCLIWith(t, []string{"bogus"}, ""); r.code != 2 {
45			t.Fatalf("unknown command code=%d", r.code)
46		}
47	}
