49	func TestCLILedgerLifecycle(t *testing.T) {
50		ledgerPath := t.TempDir() + "/ledger.json"
51	
52		// init
53		r := runCLIWith(t, []string{"init", "-l", ledgerPath},
54			`{"balances":[{"account":"aa-1","asset":"usdc","balance":2000}]}`)
55		if r.code != 0 {
56			t.Fatalf("init code=%d err=%s", r.code, r.err)
57		}
58		if v := decodeOut(t, r.out); v["status"] != "initialized" {
59			t.Fatalf("init out=%s", r.out)
60		}
61	
62		// 重复 init：退出码 1 + ledger_exists，且文件未被覆盖。
63		r = runCLIWith(t, []string{"init", "-l", ledgerPath}, `{"balances":[]}`)
64		if r.code != 1 {
65			t.Fatalf("re-init code=%d", r.code)
66		}
67		if env := decodeOut(t, r.err); env["error"].(map[string]any)["kind"] != "ledger_exists" {
68			t.Fatalf("re-init envelope=%s", r.err)
69		}
70	
71		// 非法 init：分类为 invalid_parameter。
72		badPath := t.TempDir() + "/bad.json"
73		r = runCLIWith(t, []string{"init", "-l", badPath},
74			`{"balances":[{"account":"","asset":"usdc","balance":1}]}`)
75		if r.code != 1 || decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "invalid_parameter" {
76			t.Fatalf("bad init: code=%d err=%s", r.code, r.err)
77		}
78	
79		// submit：混合结果逐项返回，退出码 0。
80		batch := `{"fee_bps":30,"intents":[
81		  {"id":"p1","account":"aa-1","paymaster":"pm","asset":"usdc","amount":1500,"nonce":1},
82		  {"id":"p2","account":"aa-1","asset":"usdc","amount":900},
83		  {"id":"p1","account":"aa-1","paymaster":"pm","asset":"usdc","amount":1500,"nonce":1},
84		  {"id":"p3","account":"aa-1","asset":"usdc","amount":1,"state":"failed"}
85		]}`
86		r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, batch)
87		if r.code != 0 {
88			t.Fatalf("submit code=%d err=%s", r.code, r.err)
89		}
90		var res struct {
91			Results []struct {
92				ID     string `json:"id"`
93				Status string `json:"status"`
94			} `json:"results"`
95		}
96		if err := json.Unmarshal([]byte(r.out), &res); err != nil {
97			t.Fatal(err)
98		}
99		got := make([]string, len(res.Results))
100		for i, x := range res.Results {
101			got[i] = x.Status
102		}
103		want := []string{"settled", "insufficient_balance", "duplicate", "state_error"}
104		if strings.Join(got, ",") != strings.Join(want, ",") {
105			t.Fatalf("statuses=%v want %v", got, want)
106		}
107	
108		// 空批次返回空结果。
109		r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, `{"fee_bps":0,"intents":[]}`)
110		if r.code != 0 || strings.TrimSpace(r.out) != `{
111	  "results": []
112	}` {
113			t.Fatalf("empty batch: code=%d out=%q", r.code, r.out)
114		}
115	
116		// 非法费率走错误信封（批次级错误，不是逐项）。
117		r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, `{"fee_bps":-2,"intents":[]}`)
118		if r.code != 1 || decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "invalid_parameter" {
119			t.Fatalf("bad fee: code=%d err=%s", r.code, r.err)
120		}
121	
122		// query（模拟新进程重新打开）。
123		r = runCLIWith(t, []string{"query", "-l", ledgerPath}, "")
124		if r.code != 0 {
125			t.Fatalf("query code=%d err=%s", r.code, r.err)
126		}
127		var snap struct {
128			Balances []struct {
129				Balance int64 `json:"balance"`
130			} `json:"balances"`
131			Settlements []struct {
132				ID      string `json:"id"`
133				FeeBps  int    `json:"fee_bps"`
134				Charged int64  `json:"charged"`
135			} `json:"settlements"`
136		}
137		if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
138			t.Fatal(err)
139		}
140		if len(snap.Balances) != 1 || snap.Balances[0].Balance != 496 {
141			t.Fatalf("query balances=%+v", snap.Balances)
142		}
143		if len(snap.Settlements) != 1 || snap.Settlements[0].ID != "p1" || snap.Settlements[0].FeeBps != 30 || snap.Settlements[0].Charged != 1504 {
144			t.Fatalf("query settlements=%+v", snap.Settlements)
145		}
146	
147		// 未初始化路径。
148		missing := t.TempDir() + "/nope.json"
149		if r = runCLIWith(t, []string{"query", "-l", missing}, ""); r.code != 1 ||
150			decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "ledger_not_initialized" {
151			t.Fatalf("missing: %+v", r)
152		}
153	}
