155	func TestCLICorruptLedger(t *testing.T) {
156		dir := t.TempDir()
157	
158		// 直接写出一个损坏账本（不经过本进程 init，绕过同进程注册表缓存，
159		// 模拟用户拿一个被截断/损坏的文件启动程序）。
160		path := dir + "/corrupt.json"
161		if err := os.WriteFile(path, []byte(`{"version":1,`), 0o600); err != nil {
162			t.Fatal(err)
163		}
164		for _, cmd := range []string{"query", "submit"} {
165			r := runCLIWith(t, []string{cmd, "-l", path}, `{"fee_bps":0,"intents":[]}`)
166			if r.code != 1 || decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "corrupt_ledger" {
167				t.Fatalf("%s on corrupt: code=%d out=%s err=%s", cmd, r.code, r.out, r.err)
168			}
169		}
170	
171		// 非法 JSON 输入分类为 invalid_parameter（与磁盘损坏区分）。
172		good := dir + "/good.json"
173		if r := runCLIWith(t, []string{"init", "-l", good}, `{"balances":[]}`); r.code != 0 {
174			t.Fatalf("init good: %s", r.err)
175		}
176		if r := runCLIWith(t, []string{"submit", "-l", good}, `{not json`); r.code != 1 ||
177			decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "invalid_parameter" {
178			t.Fatalf("garbage input: code=%d err=%s", r.code, r.err)
179		}
180	}
