189	func TestCLIRefundLifecycle(t *testing.T) {
190		ledgerPath := t.TempDir() + "/ledger.json"
191	
192		if r := runCLIWith(t, []string{"init", "-l", ledgerPath},
193			`{"balances":[{"account":"aa-1","asset":"usdc","balance":2000}]}`); r.code != 0 {
194			t.Fatalf("init: %s", r.err)
195		}
