205		// 退款批次：成功 / 重复 / 冲突 / 已退款 / 目标不存在 / 参数非法，逐项返回且退出码 0。
206		refunds := `{"refunds":[
207		  {"id":"r1","settlement_id":"p1","reason":"cancel"},
208		  {"id":"r1","settlement_id":"p1","reason":"cancel"},
209		  {"id":"r1","settlement_id":"p1","reason":"changed"},
210		  {"id":"r2","settlement_id":"p1","reason":"again"},
211		  {"id":"r3","settlement_id":"ghost","reason":"x"},
212		  {"id":"r4","settlement_id":"p2","reason":"x"},
213		  {"id":"","settlement_id":"p1","reason":"x"}
214		]}`
215		r := runCLIWith(t, []string{"refund", "-l", ledgerPath}, refunds)
216		if r.code != 0 {
217			t.Fatalf("refund batch must exit 0 even with per-item failures: %s", r.err)
218		}
219		var res struct {
220			Results []struct {
221				ID           string `json:"id"`
222				Status       string `json:"status"`
