233		if len(res.Results) != len(want) {
234			t.Fatalf("got %d results, want %d: %s", len(res.Results), len(want), r.out)
235		}
236		for i, x := range res.Results {
237			if x.Status != want[i] {
238				t.Fatalf("item %d status=%s want %s", i, x.Status, want[i])
239			}
240		}
