338			t.Fatalf("init: %s", r.err)
339		}
340		r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, `{"fee_bps":30,"intents":[
341		  {"id":"p1","account":"aa-1","paymaster":"pm","asset":"usdc","amount":1000,"nonce":1}
342		]}`)
343		if r.code != 0 {
344			t.Fatalf("submit: %s", r.err)
345		}
346		r = runCLIWith(t, []string{"refund", "-l", ledgerPath},
347			`{"refunds":[{"id":"r1","settlement_id":"p1","reason":"cancel"}]}`)
348		if r.code != 0 {
349			t.Fatalf("refund: %s", r.err)
350		}
351	
352		body := `{"entries":[
353		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003},
354		  {"kind":"payment","id":"pX","account":"aa-1","asset":"usdc","amount":9,"fee":0,"charged":9},
355		  {"kind":"refund","id":"r1","account":"aa-1","asset":"usdc","amount":1000,"fee":3,"charged":1003,"settlement_id":"p1"}
356		]}`
357		r = runCLIWith(t, []string{"reconcile", "-l", ledgerPath}, body)
358		if r.code != 0 {
359			t.Fatalf("reconcile exits 0 even with differences: %s", r.err)
360		}
361		var rep struct {
362			Results []struct {
363				Index     int    `json:"index"`
364				Kind      string `json:"kind"`
365				ID        string `json:"id"`
366				Status    string `json:"status"`
367				Positions []int  `json:"positions"`
368				Diffs     []struct {
369					Field  string `json:"field"`
370					Ledger string `json:"ledger"`
371					Flow   string `json:"flow"`
372				} `json:"diffs"`
373				Record *struct {
374					SettlementID string `json:"settlement_id"`
375					RefundID     string `json:"refund_id"`
376				} `json:"record"`
377			} `json:"results"`
378			MissingPayments []map[string]any `json:"missing_payments"`
379			MissingRefunds  []map[string]any `json:"missing_refunds"`
380			MaxPaymentSeq   int64            `json:"max_payment_seq"`
381			MaxRefundSeq    int64            `json:"max_refund_seq"`
382			Totals          struct {
383				Ledger []struct {
384					Account       string `json:"account"`
385					Asset         string `json:"asset"`
386					ChargedTotal  string `json:"charged_total"`
387					RefundedTotal string `json:"refunded_total"`
388					NetCharged    string `json:"net_charged"`
389				} `json:"ledger"`
390				Flow []struct {
391					NetCharged string `json:"net_charged"`
392				} `json:"flow"`
393			} `json:"totals"`
394			NetDiff []struct {
395				NetChargedDiff string `json:"net_charged_diff"`
396			} `json:"net_diff"`
397		}
398		if err := json.Unmarshal([]byte(r.out), &rep); err != nil {
399			t.Fatalf("decode report: %v\n%s", err, r.out)
400		}
401		if len(rep.Results) != 3 {
402			t.Fatalf("want 3 results, got %d", len(rep.Results))
403		}
404		want := []string{"matched", "missing_in_ledger", "matched"}
405		for i, x := range rep.Results {
406			if x.Status != want[i] {
407				t.Fatalf("result %d = %s want %s", i, x.Status, want[i])
408			}
409			if x.Index != i {
410				t.Fatalf("result %d index=%d", i, x.Index)
411			}
412		}
413		// 命中账本的结果都带关联记录：p1 已退款带 refund_id；r1 带 settlement_id。
414		if rep.Results[0].Record == nil || rep.Results[0].Record.RefundID != "r1" {
415			t.Fatalf("p1 record link: %+v", rep.Results[0].Record)
416		}
417		if rep.Results[2].Record == nil || rep.Results[2].Record.SettlementID != "p1" {
418			t.Fatalf("r1 record link: %+v", rep.Results[2].Record)
419		}
420		// 全部账本记录都被覆盖，缺失列表为空。
421		if len(rep.MissingPayments) != 0 || len(rep.MissingRefunds) != 0 {
422			t.Fatalf("missing=%+v/%+v", rep.MissingPayments, rep.MissingRefunds)
423		}
424		if rep.MaxPaymentSeq != 1 || rep.MaxRefundSeq != 1 {
425			t.Fatalf("max seqs=%d/%d", rep.MaxPaymentSeq, rep.MaxRefundSeq)
426		}
427		// 账本侧 usdc 扣款 1003、退款 1003、净 0；流水侧净扣款 = 1003+9-1003 = 9；差额 +9。
428		if len(rep.Totals.Ledger) != 1 || rep.Totals.Ledger[0].ChargedTotal != "1003" ||
429			rep.Totals.Ledger[0].RefundedTotal != "1003" || rep.Totals.Ledger[0].NetCharged != "0" {
430			t.Fatalf("ledger totals=%+v", rep.Totals.Ledger)
431		}
432		if rep.Totals.Flow[0].NetCharged != "9" || rep.NetDiff[0].NetChargedDiff != "9" {
433			t.Fatalf("flow net=%s diff=%s", rep.Totals.Flow[0].NetCharged, rep.NetDiff[0].NetChargedDiff)
434		}
435	}
