441		body := `{"entries":[
442		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1000,"fee":9,"charged":1003},
443		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":5,"charged":99},
444		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":5,"charged":99},
445		  {"kind":"refund","id":"rX","account":"aa-1","asset":"usdc","amount":1,"fee":0,"charged":1,"settlement_id":"p1"}
446		]}`
447		r := runCLIWith(t, []string{"reconcile", "-l", ledgerPath}, body)
448		if r.code != 0 {
449			t.Fatalf("reconcile: %s", r.err)
450		}
451		var rep struct {
452			Results []struct {
453				Status    string `json:"status"`
454				Positions []int  `json:"positions"`
455				Diffs     []struct {
456					Field string `json:"field"`
457				} `json:"diffs"`
458			} `json:"results"`
459			MissingPayments []struct {
460				ID string `json:"id"`
461			} `json:"missing_payments"`
462			MissingRefunds []struct {
463				ID string `json:"id"`
464			} `json:"missing_refunds"`
465		}
466		if err := json.Unmarshal([]byte(r.out), &rep); err != nil {
467			t.Fatalf("decode: %v\n%s", err, r.out)
468		}
469		if rep.Results[0].Status != "field_mismatch" {
470			t.Fatalf("p1 status=%s", rep.Results[0].Status)
471		}
472		var fields []string
473		for _, d := range rep.Results[0].Diffs {
474			fields = append(fields, d.Field)
475		}
476		if strings.Join(fields, ",") != "fee" {
477			t.Fatalf("p1 diffs=%v", fields)
478		}
479		for _, i := range []int{1, 2} {
480			if rep.Results[i].Status != "duplicate" {
481				t.Fatalf("result %d status=%s", i, rep.Results[i].Status)
482			}
483			pos := rep.Results[i].Positions
484			if len(pos) != 2 || pos[0] != 1 || pos[1] != 2 {
485				t.Fatalf("result %d positions=%v", i, pos)
486			}
487			if len(rep.Results[i].Diffs) != 0 {
488				t.Fatalf("duplicate must not list diffs: %+v", rep.Results[i].Diffs)
489			}
490		}
491		if rep.Results[3].Status != "missing_in_ledger" {
492			t.Fatalf("rX status=%s", rep.Results[3].Status)
493		}
494		// p2 重复组抑制缺失；p1 已覆盖（字段不符也算覆盖）。账本无退款 -> 无缺失退款。
495		if len(rep.MissingPayments) != 0 {
496			t.Fatalf("missing payments=%+v", rep.MissingPayments)
497		}
498		if len(rep.MissingRefunds) != 0 {
499			t.Fatalf("missing refunds=%+v", rep.MissingRefunds)
500		}
501	}
