	}
	// 合法空批次仍返回原有空列表。
	r = runCLIWith(t, []string{"submit", "-l", ledgerPath}, `{"fee_bps":0,"intents":[]}`)
	if r.code != 0 || strings.TrimSpace(r.out) != "{\n  \"results\": []\n}" {
		t.Fatalf("empty batch: code=%d out=%q", r.code, r.out)
	}
}
